<template>
  <section class="return-ledger">
    <div class="toolbar"><strong>{{ title }}</strong><el-button size="small" :loading="loading" @click="load">刷新记录</el-button></div>
    <p class="muted">{{ section==='RECEIPTS'?'每行是一条原始实收消息，本次数量为增量；同一消息去重显示，重复回传不重复入账。合包仅展示一次原回传。':section==='LINES'?'以下为已明确来源的实收明细；仅入账成功的行增加库存，正品和次品分别记账。':'截单后到货等异常回传独立保留，待核对记录不提前增加库存。' }}</p>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <el-table v-loading="loading" :data="rows" size="small" :empty-text="section==='REVIEWS'?'暂无异常回传核对记录':'尚无本类记录'">
      <el-table-column v-if="section==='RECEIPTS'" type="expand"><template slot-scope="{row}"><div class="expanded"><p v-if="row.allocations.length" class="muted">本次分配 {{ row.allocations.length }} 项，方式：{{ row.allocation_method==='AUTO'?'自动分配':row.actor?'人工确认':'查看来源台账' }}；各来源及入账结果在下方明细核对。</p><el-table :data="row.lines" size="mini"><el-table-column prop="sku_sn" label="仓库回传 SKU" min-width="230" /><el-table-column prop="batch_code" label="回传批次" min-width="160" /><el-table-column label="本次正品 / 次品" width="160"><template slot-scope="s">{{ s.row.good_qty }} / {{ s.row.bad_qty }}</template></el-table-column><el-table-column prop="source_line" label="仓库来源行号" /></el-table><el-table v-if="row.allocations.length" :data="row.allocations" size="mini" class="allocation-table"><el-table-column label="本次分配归属" min-width="280"><template slot-scope="s"><router-link v-if="owner(s.row)" :to="sourceLink(owner(s.row))">{{ s.row.owner_sn }}</router-link><span v-else>{{ s.row.owner_sn || '来源行 #'+s.row.member_id }}</span></template></el-table-column><el-table-column prop="sku_sn" label="实际商品 SKU" min-width="230" /><el-table-column label="分配正品 / 次品" width="170"><template slot-scope="s">{{ s.row.good_qty }} / {{ s.row.bad_qty }}</template></el-table-column><el-table-column label="原回传行" width="120"><template slot-scope="s">第 {{ Number(s.row.line_index)+1 }} 行</template></el-table-column></el-table></div></template></el-table-column>
      <el-table-column label="时间 / 回传消息" min-width="210"><template slot-scope="{row}">{{ row.create_time }}<div class="muted">{{ row.message_id }}</div></template></el-table-column>
      <el-table-column v-if="section!=='RECEIPTS'" label="所属售后 / 实际商品" min-width="250"><template slot-scope="{row}"><router-link v-if="owner(row)" :to="sourceLink(owner(row))">{{ row.owner_sn }}</router-link><span v-else>{{ row.owner_sn }}</span><div class="muted">{{ row.sku_sn }}</div><el-tag v-if="owner(row)&&owner(row).is_gift" size="mini" type="warning">赠品</el-tag><div class="muted">{{ row.batch_code ? '实际入账批次 '+row.batch_code : '' }}</div></template></el-table-column>
      <el-table-column v-if="section==='RECEIPTS'" label="本次增量 / 仓库收货确认" min-width="160"><template slot-scope="{row}"><div>{{ row.quantity }} <span class="muted">库存单位见展开明细</span></div><el-tag size="mini" :type="row.final_confirmation?'warning':'info'">{{ row.final_confirmation?'最终回传':'分批回传' }}</el-tag></template></el-table-column>
      <el-table-column v-if="section==='LINES'" label="正品 / 次品 / 入账数量" min-width="165"><template slot-scope="{row}"><div>正品 {{ row.good_qty }} · 次品 {{ row.bad_qty }}</div><div>{{ row.posted===1?'已入账':'待入账' }} {{ Number(row.good_qty)+Number(row.bad_qty) }} {{ owner(row)?owner(row).unit:'' }}</div></template></el-table-column>
      <el-table-column v-if="section==='LINES'" label="入账成本 / 流水关联号" min-width="230"><template slot-scope="{row}"><div>原出库成本 ¥{{ row.unit_cost }} / {{ owner(row)?owner(row).unit:'库存单位' }}</div><div class="muted">{{ row.inventory_relation }}</div><div class="muted">{{ row.posted===1?'该关联号已确认入账':'该关联号尚未确认入账' }}</div></template></el-table-column>
      <el-table-column label="处理结果 / 原因" min-width="230"><template slot-scope="{row}"><el-tag size="mini" :type="section==='LINES'?(row.posted===1?'success':'warning'):['WAIT_REVIEW','WAIT_ALLOCATION','FAILED'].includes(row.state)?'warning':'info'">{{ section==='LINES'?(row.posted===1?'入账成功':row.last_error?'入账待重试':'待入账'):section==='REVIEWS'?({'WAIT_REVIEW':'待人工核对','ACCEPTED':'已确认接收','REJECTED':'已拒绝'}[row.state]||row.state):receiptLabel(row) }}</el-tag><div class="warning">{{ row.last_error || row.reason }}</div><div v-if="row.actor" class="muted">处理人 {{ row.actor }}</div></template></el-table-column>
      <el-table-column label="交互" width="95"><template slot-scope="{row}"><el-button v-if="row.source_log_id" type="text" @click="$emit('interaction',row.source_log_id)">查看回传</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total>0" :total="total" :page.sync="page" :limit.sync="size" :page-sizes="[20,50]" @pagination="load" />
  </section>
</template>
<script>
import { returnDocument } from '@/api/order/returns'
import { sourceLink } from './returnManagementPresentation'
import { receiptLabel } from './returnDocumentPresentation'
export default {
  props: { sn: { type: String, required: true }, section: { type: String, required: true }, members: { type: Array, default: () => [] } }, data: () => ({ rows: [], total: 0, page: 1, size: 20, loading: false, sequence: 0, error: '' }),
  computed: { title() { return { RECEIPTS: '逐次仓库实收回传', LINES: '来源实收与库存入账明细', REVIEWS: '异常回传核对记录' }[this.section] } },
  watch: { sn: { immediate: true, handler() { this.page = 1; this.load() } } }, beforeDestroy() { this.sequence++ },
  methods: { sourceLink, receiptLabel, owner(row) { return this.members.find(m => m.owner_sn === row.owner_sn && (!row.sku_sn || row.sku_sn === m.sku_sn)) }, async load() { const seq = ++this.sequence; this.loading = true; this.error = ''; try { const r = (await returnDocument({ sn: this.sn, section: this.section, pageNum: this.page, pageSize: this.size })).data; if (seq !== this.sequence) return; this.rows = r.rows || []; this.total = Number(r.total) } catch (_) { if (seq === this.sequence) { this.rows = []; this.total = 0; this.error = '本类记录加载失败，请刷新重试；未知结果未按0处理' } } finally { if (seq === this.sequence) this.loading = false } } }
}
</script>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:22px 0 10px}.muted{font-size:12px;color:#7a899d;line-height:1.8;overflow-wrap:anywhere}.warning{font-size:12px;line-height:1.8;color:#b77d19;overflow-wrap:anywhere}.expanded{padding:0 24px 10px}.allocation-table{margin-top:18px}.return-ledger ::v-deep td{vertical-align:top}</style>
